}

interface ClientAlertRow {
  id: string;
  severity: string | null;
  createdAt: Date;
  title: string;
  whyItMatters: string | null;
  recommendedAction: string | null;
}

interface ActionMilestoneSource {
  id: string;
  date: Date;
  text: string;
  type: string | null;
  chamber: string | null;
}
